struct H{uint64_t r=0;array<uint16_t,4>i{};bool operator<(H const&z)const{return r<z.r;}};
static inline array<uint16_t,CMAX> addc(auto const&a,auto const&b,auto const&m){array<uint16_t,CMAX>z{};for(int i=0;i<CMAX;i++){unsigned v=(unsigned)a[i]+b[i];if(v>=m[i])v-=m[i];z[i]=(uint16_t)v;}return z;}
static uint64_t enc(auto const&a,vector<int>const&ix,auto const&m){uint64_t z=0,p=1;for(int j:ix){z+=p*a[j];p*=m[j];}return z;}
static uint64_t ord(vector<int>const&ix,auto const&m){uint64_t p=1;for(int j:ix)p*=m[j];return p;}
static uint64_t sub(uint64_t a,uint64_t b,vector<int>const&ix,auto const&m){uint64_t z=0,p=1;for(int j:ix){int q=m[j],x=a%q,y=b%q,d=x-y;if(d<0)d+=q;z+=p*d;p*=q;a/=q;b/=q;}return z;}
static vector<P> pairs(B const&a,B const&b,auto const&m){vector<P>v;v.reserve(a.o.size()*b.o.size());for(int i=0;i<(int)a.o.size();i++)for(int j=0;j<(int)b.o.size();j++)v.push_back({addc(a.o[i].c,b.o[j].c,m),(uint16_t)i,(uint16_t)j});return v;}
struct BK{vector<int>ofs,ids;vector<uint32_t>pc;};
static BK bucket(vector<P>const&v,vector<int>const&pre,auto const&m){uint64_t bc64=ord(pre,m);if(bc64>200000000ULL)throw runtime_error("b");int bc=(int)bc64;BK z;z.ofs.assign(bc+1,0);z.ids.resize(v.size());z.pc.resize(v.size());for(int i=0;i<(int)v.size();i++){uint32_t c=(uint32_t)enc(v[i].c,pre,m);z.pc[i]=c;z.ofs[c+1]++;}for(int i=0;i<bc;i++)z.ofs[i+1]+=z.ofs[i];vector<int>pos=z.ofs;for(int i=0;i<(int)v.size();i++)z.ids[pos[z.pc[i]]++]=i;return z;}
static vector<H> merge2(vector<P>const&A,vector<P>const&Bv,BK const&bb,vector<uint32_t>const&ap,vector<int>const&pre,vector<int>const&rem,uint64_t goal,auto const&m){vector<H>out;long double ex=(long double)A.size()*Bv.size()/bb.ofs.size();out.reserve((size_t)(ex*1.10+1000));for(int ai=0;ai<(int)A.size();ai++){auto&a=A[ai];uint64_t need=sub(goal,ap[ai],pre,m);for(int p=bb.ofs[need];p<bb.ofs[need+1];p++){auto&b=Bv[bb.ids[p]];auto c=addc(a.c,b.c,m);out.push_back({enc(c,rem,m),{a.a,a.b,b.a,b.b}});}}return out;}
static int vp5(long long d,int E){int e=0;long long m=5;for(;e<E;e++,m*=5)if(d%m)return e;return E;}
